    statusNote: "プレゼントの内容と応募期間は主催者の公式案内に基づきます。対象施設の一覧は公式ページでご確認ください。関連施設として挙げた湯らっくすは熊本のサウナの紹介であり、対象施設であることを示すものではありません。",
