    title: "築50年の銭湯が、黄金湯の2号店になった。東新宿の「THE CAVE」は男女で別の顔を見せる",
    lead: "墨田区錦糸町の老舗銭湯「黄金湯」の2号店として東新宿に開いた黄金湯 新宿が、SAUNACHELIN 2026で6位に入りました。引き継がれた銭湯の経緯と、公式ページで確認できる料金・営業時間をまとめます。",
